        cMtx_multVec(camMtx, &sp94, &sp88);
        pos[0].x = sp7C.x + sp88.x;
        pos[0].y = sp7C.y + sp88.y;
        pos[0].z = sp7C.z + sp88.z;

        sp94.x = var_f30 * sp44;
        sp94.y = var_f30;
        sp94.z = 0.0f;
        cMtx_multVec(camMtx, &sp94, &sp88);
        pos[1].x = sp7C.x + sp88.x;
        pos[1].y = sp7C.y + sp88.y;
        pos[1].z = sp7C.z + sp88.z;

        sp94.x = var_f30 * sp44;
        sp94.y = -var_f30;
