    Mtx camMtx;
    Mtx rotMtx;
    cXyz pos[4];
    cXyz windvec;
    cXyz vp;
    cXyz lp;
    cXyz p;
    cXyz dummy;
    cXyz tilt;

    if (pPkt->mCount <= 0)
        return;

    j3dSys.reinitGX();
    if (dComIfGd_getView() != NULL) {
        MTXInverse(dComIfGd_getViewRotMtx(), camMtx);
    } else {
        return;
    }

